class AcpRequestConsumer(MroDispatch):

    def __init__(self, agent, session_id, prompt):
        self.agent, self.session_id, self.prompt = (agent, session_id, prompt)
        self.response = None

    async def run(self, request):
        await self.dispatch(request)
        if self.response is None:
            raise RuntimeError('Declared ACP request has no response handler')
        return self.response

    async def forward(self, request):
        result = await self.agent.sessions.proxies[self.session_id].request('prompt', meta=encode_request(request), prompt=[block if isinstance(block, dict) else block.model_dump(by_alias=True, exclude_none=True) for block in self.prompt])
        return PromptResponse.model_validate(result)

    @handles(PromptRequest)
    async def prompt_request(self, request):
        if self.session_id in self.agent.sessions.proxies:
            self.response = await self.forward(request)
            return
        self.response = await self.agent._prompt_request(self.session_id, self.prompt, request)

    @handles(CompactRequest)
    async def compact(self, request):
        self.agent._require_compaction_text(self.prompt)
        if self.agent._prompt_text(self.prompt).strip() and (not self.agent._prompt_text(self.prompt).strip().startswith('/compact')):
            raise RequestError.invalid_params({'reason': 'Compaction metadata requires blank text'})
        self.response = await self.agent._compact_request(self.session_id, request.instructions)

    @handles(SelectedWriteRequest)
    async def selected_write(self, request):
        if self.prompt:
            raise RequestError.invalid_params({'reason': 'Selected write requires no prompt'})
        if self.session_id in self.agent.sessions.proxies:
            self.response = await self.forward(request)
            return
        self.response = await self.agent._selected_write_request(self.session_id, request)

    @handles(ClearQueueRequest)
    async def clear(self, request):
        if self.session_id in self.agent.sessions.proxies:
            await self.agent.sessions.proxies[self.session_id].request('clear_queue')
        else:
            await self.agent.inputs.clear_queued_inputs(self.session_id)
        self.response = PromptResponse(stop_reason='end_turn')

    @handles(SendNowRequest)
    async def send_now(self, request):
        if self.session_id in self.agent.sessions.proxies:
            self.response = await self.forward(request)
            return
        self.agent.inputs.send_now(self.session_id)
        self.response = PromptResponse(stop_reason='end_turn')

class AgentEventConsumer(MroDispatch, ABC):
    """Shared activity and metadata algorithms; owners supply their context."""

    @property
    @abstractmethod
    def comms(self) -> Comms:
        pass

    @property
    @abstractmethod
    def thread_name(self) -> str:
        pass

    async def before_agent_info(self, event: AgentInfo) -> None:
        pass

    async def after_agent_info(self, event: AgentInfo) -> None:
        pass

    @handles(AgentInfo)
    async def record_agent_info(self, event: AgentInfo) -> None:
        await self.before_agent_info(event)
        self.comms.agents.set_agent_info(self.thread_name, model=event.model, session_name=event.session_name, context_used=event.context_used, context_size=event.context_size)
        await self.after_agent_info(event)

class DispatchCases(MroDispatch):
    """Collect cases of one external Python AST without executing its source."""
    minimum_arms = 3

    def __init__(self) -> None:
        self.cases: dict[str, set[str]] = {}

    def add(self, subject: ast.AST, case: str) -> None:
        self.cases.setdefault(ast.dump(subject), set()).add(case)

    def groups(self) -> tuple[frozenset[str], ...]:
        return tuple((frozenset(cases) for cases in self.cases.values() if len(cases) >= self.minimum_arms))

    def read_function(self, function: ast.AST) -> None:
        pending = list(ast.iter_child_nodes(function))
        while pending:
            node = pending.pop()
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda, ast.ClassDef)):
                continue
            self.dispatch_sync(node)
            pending.extend(ast.iter_child_nodes(node))

class TypingImports(MroDispatch):
    """Resolve unshadowed module imports from the actual stdlib declarations.

    This bounded syntactic measure never executes inspected source. Nested
    bindings conservatively disqualify a name rather than inferring its flow.
    """

    def __init__(self, declarations: set[ast.AST]) -> None:
        self.declarations = declarations
        self.values: dict[str, object] = {}
        self.shadowed: set[str] = set()

    def bind(self, node: ast.AST, name: str, value: object) -> None:
        if node not in self.declarations or name in self.values:
            self.shadowed.add(name)
        self.values[name] = value

    @handles(ast.Import)
    def modules(self, node: ast.Import) -> None:
        for item in node.names:
            self.bind(node, item.asname or item.name.split('.')[0], typing if item.name == typing.__name__ else None)

    @handles(ast.ImportFrom)
    def members(self, node: ast.ImportFrom) -> None:
        for item in node.names:
            declaration = None
            if node.level == 0 and node.module == typing.__name__:
                declaration = vars(typing).get(item.name)
            self.bind(node, item.asname or item.name, declaration)

    @handles(ast.Name)
    def assignment(self, node: ast.Name) -> None:
        if isinstance(node.ctx, (ast.Store, ast.Del)):
            self.shadowed.add(node.id)

    @handles(ast.Attribute)
    def mutation(self, node: ast.Attribute) -> None:
        if isinstance(node.ctx, (ast.Store, ast.Del)):
            for descendant in ast.walk(node.value):
                if isinstance(descendant, ast.Name):
                    self.shadowed.add(descendant.id)

    @handles(ast.arg)
    def parameter(self, node: ast.arg) -> None:
        self.shadowed.add(node.arg)

    @handles(ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)
    def named_binding(self, node) -> None:
        self.shadowed.add(node.name)

    @handles(ast.ExceptHandler)
    def exception_binding(self, node: ast.ExceptHandler) -> None:
        name = node.name
        if name is not None:
            self.shadowed.add(name)
    if hasattr(ast, 'type_param'):

        @handles(ast.type_param)
        def type_parameter(self, node) -> None:
            self.shadowed.add(node.name)

    @classmethod
    def of(cls, tree: ast.Module) -> dict[str, object]:
        imports = cls(set(tree.body))
        for node in ast.walk(tree):
            imports.dispatch_sync(node)
        if '*' in imports.values:
            return {}
        return {name: value for name, value in imports.values.items() if name not in imports.shadowed}

class TypingReference(MroDispatch):
    """One AST expression's resolved imported declaration, never evaluated code."""

    def __init__(self, imports: dict[str, object]) -> None:
        self.imports = imports
        self.value: object = None

    @handles(ast.Name)
    def name(self, node: ast.Name) -> None:
        self.value = self.imports.get(node.id)

    @handles(ast.Attribute)
    def member(self, node: ast.Attribute) -> None:
        parent = TypingReference(self.imports)
        parent.dispatch_sync(node.value)
        if parent.value is typing:
            self.value = vars(typing).get(node.attr)

    def raw_access_count(self) -> int:
        """Typing declarations contribute no raw-record operation; unknowns do."""
        return int(getattr(self.value, '__module__', None) != typing.__name__)

class FailureDecoder(MroDispatch):

    def __init__(self):
        self.failure = None

    @handles(HumanInitialUnknownError)
    def unknown(self, error):
        self.failure = UnknownDeliveryFailure(str(error), error.wire_root_id, error.wire_seq, error.message_id)

    @handles(HumanAdmissionBlockedError)
    def blocked(self, error):
        self.failure = AdmissionBlockedFailure(str(error))

    @handles(Exception)
    def refused(self, error):
        if self.failure is None:
            self.failure = BackendDeliveryFailure(str(error))

class DurableTurn(MroDispatch):

    def __init__(self, attempts: AttemptStore, fence, pointer_revision, input_id):
        self.attempts = attempts
        self.fence = fence
        self.pointer_revision = pointer_revision
        self.input_id = input_id

    @contextmanager
    def using_attempts(self, attempts):
        """Borrow only this operation's connection; keep the original fence owner."""
        original = self.attempts
        self.attempts = attempts
        try:
            yield
        finally:
            self.attempts = original

    async def consume_handlers(self, event, handlers):
        return await Coordination.run_async(self.attempts.session.path, partial(self.observe_owned, event, handlers))

    def observe_owned(self, event, handlers, resource):
        """Consume one native observation through joined, worker-owned SQLite."""
        with self.using_attempts(resource.attempts):
            return self.consume_handlers_sync(event, handlers)

    @property
    def current(self):
        return type(self.attempts.require_fence(self.fence)[1].lifecycle)

    @property
    def model_started(self):
        return self.current.has_model_context

    def advance(self, state):
        if state is self.current:
            return
        result = self.attempts.advance(self.fence, state, expected_pointer_revision=self.pointer_revision, progress=True).value
        self.fence = result.fence

    @handles(pi.Response)
    def accepted(self, event):
        if event.id == 'native-prompt' and event.success and self.current.starting:
            self.advance(PromptAcceptedAttempt)

    @handles(pi.ContextCommitted)
    def context(self, event):
        if event.input_id != self.input_id or self.model_started:
            return
        if self.current.starting:
            self.advance(PromptAcceptedAttempt)
        self.advance(ModelRunningAttempt)

    @handles(NativePhaseChanged)
    def excursion(self, event):
        if self.model_started:
            self.dispatch_sync(event.phase)

    @handles(ModelWaitPhase)
    def model(self, phase):
        self.advance(ModelRunningAttempt)

    @handles(ToolRunningPhase)
    def tool(self, phase):
        self.advance(ToolRunningAttempt)

    @handles(CompactionPhase)
    def compaction(self, phase):
        self.advance(CompactionAttempt)

    def finish(self):
        """Native child is reaped and any explicit owner effect has completed."""
        if not self.model_started:
            raise IdentityConflict('native completion lacks model progress')
        self.fence = self.attempts.advance(self.fence, SettlingAttempt, expected_pointer_revision=self.pointer_revision, backend_done=True, process_dead=True, progress=True).value.fence
        return self.fence

    def fail_unknown(self):
        """Retire the reaped local backend without granting acceptance or replay.

        The caller holds the live registry owner boundary. Native execution has
        returned through child/tool cleanup; possible remote effects stay UNKNOWN.
        Coordination owns the atomic replay/finality/slot mutation.
        """
        return self.attempts.fail_unknown(self.fence, expected_pointer_revision=self.pointer_revision).value

    def fail_terminal(self):
        """Settle the corroborated failed input after its native child is reaped."""
        final = self.attempts.advance(self.fence, self.current, expected_pointer_revision=self.pointer_revision, backend_done=True, process_dead=True, reason_code='native_terminal_failure').value
        return self.attempts.settle_nonpublication(final.fence, expected_pointer_revision=final.snapshot.pointer_revision, outcome=AttemptFailedAttempt(), reason_code='native_terminal_failure').value

def handlers_for(self, value: Any):
    methods: dict[str, Any] = {}
    for owner in type(self).__mro__:
        for name, method in vars(owner).items():
            methods.setdefault(name, method)
    for capability in type(value).__mro__:
        for name, method in methods.items():
            if capability in getattr(method, '__handled_classes__', ()):
                yield getattr(self, name)

def dispatch_sync(self, value: Any) -> Any:
    """Consume saved presentation facts without introducing an event loop."""
    return self.consume_handlers_sync(value, self.handlers_for(value))

def consume_handlers_sync(self, value: Any, handlers: Iterable[Handler]) -> Any:
    for handler in handlers:
        value = self.replace_value(value, handler(value))
    return value

class TrackedTurnSession(TurnSession, MroDispatch):
    """Own one strict input/proof exchange; never grant publication or retry authority."""

    def __init__(self, launch, command, *, provider, model, model_wait_timeout, prompt_send_boundary, maintenance_root, startup: NativeStartupAdmission, selected_tool_mode, observe_event, request_observer):
        super().__init__(launch, command.message, model_wait_timeout=model_wait_timeout, startup=startup, request_observer=request_observer)
        self.command = command
        self.provider, self.model = (provider, model)
        self.prompt_send_boundary = prompt_send_boundary
        self.maintenance_root = maintenance_root
        self.selected_tool_mode, self.observe_event = (selected_tool_mode, observe_event)
        self.tool_socket: OwnerToolSocket | None = None
        self.input_commit: NativeCommitObservation[pi.InputCommitted] = PendingNativeCommit()
        self.context_commit: NativeCommitObservation[pi.ContextCommitted] = PendingNativeCommit()
        self.text_parts: list[str] = []
        self.terminal: TrackedTerminal = PendingTrackedTerminal()
        self.finished = False

    @classmethod
    async def execute(cls, package: Path, *, input_id: str, prompt: str, context_contributions: tuple[InputContributionCoordinates, ...]=(), worktree: Path, session: SelectedSession, provider: str='openrouter', model: str='z-ai/glm-5.3-flash', thinking_level: str | None=None, environment: dict[str, str] | None=None, model_wait_timeout: float | None=MODEL_WAIT_TIMEOUT_SECONDS, prompt_send_boundary: PrivateSendAdmission | None=None, maintenance_root: Path | None=None, selected_tool_mode: NativeToolMode | None=None, observe_event: Callable[[pi.PiEvent | AgentEvent | ObservedAttestation], Awaitable[None]] | None=None, acquisition_measurements: PublicationMeasurements | None=None, request_observer: Callable[[RequestProgress, ProcessIdentity], None] | None=None) -> NativeTurnResult:
        if type(input_id) is not str or re.fullmatch('[0-9a-f]{32}', input_id) is None:
            raise ValueError('A native turn requires a 128-bit lowercase hex input ID')
        if not prompt or not isinstance(prompt, str):
            raise ValueError('A native turn requires a nonempty prompt')
        if model_wait_timeout is not None and (not math.isfinite(model_wait_timeout) or model_wait_timeout <= 0):
            raise ValueError('A model progress wait must be positive and finite')
        launch = NativePiRpcLaunch.tracked(package, worktree=worktree, session=session, provider=provider, model=model, thinking_level=thinking_level, environment=environment, selected_tool_mode=selected_tool_mode)
        turn = cls(launch, commands.Prompt(id='native-prompt', input_id=input_id, message=prompt, context_contributions=context_contributions), provider=provider, model=model, model_wait_timeout=model_wait_timeout, prompt_send_boundary=prompt_send_boundary, maintenance_root=maintenance_root, startup=session.startup_admission(launch, maintenance_root, prompt_send_boundary, measurements=acquisition_measurements), selected_tool_mode=selected_tool_mode, observe_event=observe_event, request_observer=request_observer)
        return await turn.complete()

    async def complete(self) -> NativeTurnResult:
        async with AsyncExitStack() as custody:
            retirement = self.startup.measurements.operation('native_custody_retirement')
            custody.push(retirement)
            try:
                self.custody = custody
                self.native = await self.acquire_native(custody, reuse=False)
                custody.push_async_callback(self.native_session.close)
                await custody.enter_async_context(self.native.failures())
                custody.callback(self.native.reader.pending.cancel_all)
                if self.tool_socket is not None:
                    self.tool_socket.expected_pid = self.native.proc.pid
                self.watchdog.reading()
                try:
                    try:
                        await self.attest()
                        if self.prompt_send_boundary is not None:
                            with self.startup.measurements.operation('selected_context_preparation'):
                                await self.prompt_send_boundary.prepare_context(self)
                        await self.admit_prompt()
                        while not self.finished:
                            event = await self.next_event()
                            async for update in self.consume_native_event(event):
                                if self.observe_event is not None:
                                    await self.observe_event(update)
                            if not self.finished and self.observe_event is not None:
                                await self.observe_event(event)
                        return await self.result()
                    except (SelectedToolDenied, PromptSendFailure, TimeoutError, OSError) as error:
                        raise NativePiUnavailable(f'Native Pi operation failed: {type(error).__name__}: {error}') from error
                except NativePiUnavailable as error:
                    self.admission.raise_native_failure(error, self.native.attestation)
            finally:
                custody.callback(retirement.__enter__)

    async def resume_prepared(self, resources: AsyncExitStack) -> None:
        await super().resume_prepared(resources)
        if self.tool_socket is not None:
            self.tool_socket.expected_pid = self.native.proc.pid
        self.watchdog.reading()
        await self.attest()

    async def open_transport(self, custody: AsyncExitStack) -> None:
        if self.selected_tool_mode is not None:
            self.tool_socket = self.selected_tool_mode.socket(self.launch.session.directory, os.urandom(32).hex())
            custody.push_async_callback(self.tool_socket.close)
            await self.tool_socket.start()
            self.launch.env['AGENT_COMMS_SELECTED_TOOL_SOCKET'] = str(self.tool_socket.path)
            self.launch.env['AGENT_COMMS_SELECTED_TOOL_TOKEN'] = self.tool_socket.token

    @property
    def started_input(self):
        return self.input_commit.observed

    @property
    def active_tools(self):
        return self.tool_socket.active_tools if self.tool_socket is not None else set()

    async def apply_native_event(self, event):
        await self.dispatch(event)
        if False:
            yield

    async def next_event(self) -> pi.PiEvent:
        try:
            raw = await self.watchdog.read(self)
            event = PiRpcChannel.decode_record(raw, strict=True) if raw else None
        except (UnicodeError, ValueError, TypeError) as error:
            raise NativePiUnavailable(f'Native Pi RPC record is invalid or incomplete; {type(error).__name__}: {error}') from error
        if event is None:
            await self.native.proc.finish()
            stderr = await self.native.stderr_task
            raise NativePiUnavailable(f"Native Pi RPC record is incomplete; native exit={self.native.proc.returncode}; stderr={stderr or '(empty)'}")
        return event

    async def send(self, command: commands.PiCommand) -> None:
        payload = self.native.reader.encode(command)
        if self.maintenance_root is not None:
            try:
                async with MaintenanceBarrier(self.maintenance_root / 'registry.json').admit_ingress_async():
                    self.write(command, payload)
            except RelationViolationError as error:
                raise NativePiUnavailable('Maintenance closed before Pi capability preflight') from error
        else:
            self.write(command, payload)
        await asyncio.wait_for(self.native.proc.stdin.drain(), timeout=self.watchdog.read_timeout(self))

    async def attest(self) -> None:
        request = self.native.attestation.request
        with self.startup.measurements.operation('get_state_send'):
            await self.send(request)
        with self.startup.measurements.operation('get_state_receive'):
            event = await self.next_event()
        if not isinstance(event, pi.Response) or self.native.reader.correlate(event) is not request:
            raise NativePiUnavailable('Native Pi emitted an unexpected preflight event')
        try:
            observed = self.native.attestation.accept(event)
        except AttestationError as error:
            raise NativePiUnavailable(str(error)) from error
        state = observed.state
        if observed.identity is None:
            raise NativePiUnavailable('Native Pi omitted its private session identity')
        self.active_session_file = self.launch.session.attest(observed.identity)
        self.native.attestation = observed
        self.startup.release()
        self.startup.attest(state)
        if self.observe_event is not None:
            with self.startup.measurements.operation('attestation_publication'):
                await self.observe_event(observed)

    def write(self, command: commands.PiCommand, payload: bytes) -> None:
        if command is self.command:
            self.grant_prompt()
        self.native.proc.stdin.write(payload)

    @contextmanager
    def prompt_boundary(self):
        with self.startup.prompt_boundary(self.prompt_send_boundary, self.native.attestation.identity):
            self.grant_prompt()
            yield

    async def admit_prompt(self) -> None:
        if self.prompt_send_boundary is None:
            await self.send(self.command)
        else:
            with self.startup.measurements.operation('prompt_writer_join'):
                await send_fenced_prompt(self.native.proc.stdin, self.native.reader.encode(self.command), self.prompt_boundary, measurements=self.startup.measurements)

    @handles(pi.Response)
    async def response(self, event: pi.Response) -> None:
        request = self.native.reader.correlate(event)
        if event.id == self.command.id:
            if request is not self.command:
                raise NativePiUnavailable('Native Pi prompt acknowledgement differs')
            if event.success is not True:
                raise NativePiPromptRejected(event)
            self.admission = self.admission.acknowledge(event)
        elif issubclass(event.command, commands.MutatesSession):
            raise NativePiUnavailable('Native Pi session identity changed during a turn')

    @handles(pi.InputCommitted)
    async def committed_input(self, event: pi.InputCommitted) -> None:
        if event.input_id == self.command.input_id:
            self.input_commit = self.input_commit.capture(event)
            self.evidence = self.custody.enter_context(NativeEntry.open_input_evidence(self.active_session_file))
            await asyncio.to_thread(self.evidence.observe)

    @handles(pi.ContextCommitted)
    async def committed_context(self, event: pi.ContextCommitted) -> None:
        if event.input_id == self.command.input_id:
            self.context_commit = ObservedNativeCommit(event)

    @handles(pi.MessageUpdate)
    async def message_update(self, event: pi.MessageUpdate) -> None:
        if event.assistant_message_event is not None:
            await self.dispatch(event.assistant_message_event)

    @handles(TextDelta)
    async def text_delta(self, delta: TextDelta) -> None:
        self.text_parts.append(delta.delta)

    @handles(pi.MessageEnd)
    async def message_end(self, event: pi.MessageEnd) -> None:
        event.message.tracked_end(self)

    def accept_tool_round(self, message):
        if self.tool_socket is None:
            return False
        self.tool_socket.announce(message.content)
        self.text_parts.clear()
        self.terminal = self.terminal.tool_round()
        return True

    def accept_final_message(self, message):
        if self.tool_socket is not None:
            self.tool_socket.assert_complete()
        self.terminal = self.terminal.append(message.authoritative_text)

    def fail_terminal(self, text: str):
        self.terminal = self.terminal.fail(text)

    async def context_proof(self) -> NativeContextProof:
        if not self.admission.acknowledged:
            raise NativePiUnavailable('Native Pi did not commit a tracked model context')
        return await Coordination.run_worker(partial(_verify_context, self.active_session_file, self.command.input_id, self.native.attestation.identity.session_id, self.input_commit.require(), self.context_commit.require(), evidence=self.evidence))

    @handles(pi.ToolExecutionStart)
    async def tool_started(self, event: pi.ToolExecutionStart) -> None:
        if self.tool_socket is None:
            raise NativePiUnavailable('Native Pi tool preceded tracked context proof')
        await self.context_proof()
        self.tool_socket.tool_started(event)

    @handles(pi.ToolExecutionEnd)
    async def tool_finished(self, event: pi.ToolExecutionEnd) -> None:
        if self.tool_socket is None:
            raise NativePiUnavailable('Native Pi tool has no owner policy')
        self.tool_socket.tool_finished(event, self.command.input_id)

    @handles(pi.AgentSettled)
    async def settled(self, event: pi.AgentSettled) -> None:
        with self.startup.measurements.operation('native_agent_settled'):
            self.finished = True

    async def result(self) -> NativeTurnResult:
        with self.startup.measurements.operation('native_terminal_result'):
            with self.startup.measurements.operation('native_terminal_proof'):
                proof = await self.context_proof()
            self.terminal.raise_failure(proof, self.provider, self.model)
            if self.tool_socket is not None:
                self.tool_socket.assert_complete()
            response = self.terminal.require_response(self.text_parts)
            if self.selected_tool_mode is not None:
                await self.selected_tool_mode.finish()
            return NativeTurnResult(response.strip(), proof, self.tool_socket.selected_call_id if self.tool_socket else None)

@dataclass
class VerifiedGoalSettlement(MroDispatch):
    store: GoalAttemptStore
    permit: LaunchPermit | None
    goal: Goal
    turn: TurnId

    @property
    def progress_witness(self) -> str:
        return f'native-terminal:{self.turn.value}'

    @property
    def completion_witness(self) -> str:
        return f'registry-revision:{self.goal.revision}'

    @handles(ActiveGoal, PausedGoal)
    def progress(self, state) -> None:
        if self.permit is not None:
            self.permit.record_verified_progress(self.store, self.progress_witness)

    @handles(CompletedGoal)
    def completion(self, state: CompletedGoal) -> None:
        if self.permit is not None and self.goal.reported_turn == self.turn.value:
            self.permit.record_verified_completion(self.store, self.completion_witness)

@dataclass(frozen=True)
class FailedGoalOrigin(MroDispatch):
    comms: Comms
    thread_name: str
    goal: Goal

    @handles(ActiveGoal, CompletedGoal)
    def block(self, state) -> None:
        self.comms.goals.update_goal(self.thread_name, BlockedGoalAction(expect=GoalPrecondition(goal_id=self.goal.id, expected_goal=self.goal), progress='Goal origin turn did not finish successfully.'))

@dataclass(kw_only=True)
class TurnEventPublication(MroDispatch):
    comms: Comms
    sessions: SessionLifecycle
    effects: TurnEffects
    sync_goal_execution: Callable[[str, str], Awaitable[None]]
    session_id: str

    @handles(events.InputStarted, events.Done, events.StreamSettled, events.ToolEnd)
    async def sync_goals(self, event: events.InputStarted) -> None:
        await self.sync_goal_execution(self.session_id, self.sessions.bindings[self.session_id])

class CompactionObservation(MroDispatch):
    """All selected/native compaction callers update the existing turn owner."""

    def __init__(self, runner, session_id, lease, phase):
        self.runner, self.session_id, self.lease, self.phase = (runner, session_id, lease, phase)

    async def publish(self, phase):
        await self.runner.transition_turn(self.session_id, self.lease, phase)

    @handles(events.CompactionStart)
    async def start(self, event):
        await self.publish(self.phase.compacting())

    @handles(events.CompactionSummaryProgress)
    async def summary_progress(self, event):
        await self.publish(self.phase.compacting().measured(event.operation_id, event.source))

    @handles(events.CompactionEnd)
    async def end(self, event):
        await self.publish(self.phase.compaction_ended())
